import React, { useState, useEffect, useRef } from 'react';
import {
Container, Navbar, Nav, Row, Col, Card, Button,
Form, InputGroup, Spinner, Alert, Badge, ProgressBar
} from 'react-bootstrap';
import {
Heart, Zap, Copy, CheckCircle, Award,
Send, Facebook, Twitter, Instagram, LayoutGrid,
TrendingUp, Users, Shield, Globe, Sparkles,
ArrowRight, Check, X, Loader2, Gift, Menu
} from 'lucide-react';
import { motion, AnimatePresence, useScroll, useTransform, useSpring } from 'framer-motion';
import confetti from 'canvas-confetti';

// Import components
import HeroSection from './components/HeroSection';
import CausesSection from './components/CausesSection';
import NewsSection from './components/NewsSection';
import MajorDonorsSection from './components/MajorDonorsSection';
import PartnersSection from './components/PartnersSection';

// --- CONFIGURATION ---
const API_URL = "http://localhost:5003/api";

// Couleurs du drapeau (Burkina Faso) avec variations modernes
const COLORS = {
green: "#009E49",
red: "#EF2B2D",
yellow: "#FCD116",
dark: "#1a1a1a",
light: "#f8f9fa",
gradient: "linear-gradient(135deg, #009E49 0%, #EF2B2D 50%, #FCD116 100%)"
};

// Animations variants
const containerVariants = {
hidden: { opacity: 0 },
visible: {
opacity: 1,
transition: {
delayChildren: 0.3,
staggerChildren: 0.2
}
}
};

const itemVariants = {
hidden: { y: 20, opacity: 0 },
visible: {
y: 0,
opacity: 1,
transition: {
type: "spring",
stiffness: 100
}
}
};

const cardVariants = {
hidden: { scale: 0.8, opacity: 0 },
visible: {
scale: 1,
opacity: 1,
transition: {
type: "spring",
stiffness: 80,
damping: 15
}
},
hover: {
scale: 1.05,
transition: {
type: "spring",
stiffness: 400,
damping: 10
}
}
};

// Simplified causes for the donation flow
const CAUSES = [
{ 
id: 1, 
title: "Soutien Patriotique", 
desc: "Aide directe aux forces engagées et aux déplacés internes.", 
priority: "high"
},
{ 
id: 2, 
title: "Contribution à Faso Meebo", 
desc: "Financement de projets d'infrastructures communautaires.", 
priority: "medium"
},
{ 
id: 3, 
title: "Mémorial Thomas Sankara", 
desc: "Préservation de la mémoire et de l'héritage révolutionnaire.", 
priority: "high"
},
];

const App = () => {
const [step, setStep] = useState(0); // 0 = main site, 1+ = donation flow
const [amount, setAmount] = useState(1000);
const [selectedCause, setSelectedCause] = useState(CAUSES[0]);
const [invoice, setInvoice] = useState("");
const [loading, setLoading] = useState(false);
const [error, setError] = useState(null);
const [copied, setCopied] = useState(false);
const [scrolled, setScrolled] = useState(false);
const [paymentProgress, setPaymentProgress] = useState(0);
const [showSuccess, setShowSuccess] = useState(false);
const [totalDonations, setTotalDonations] = useState(8500000);
const [activeDonors, setActiveDonors] = useState(36500);
const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

// Scroll animations
const { scrollYProgress } = useScroll();
const backgroundY = useTransform(scrollYProgress, [0, 1], [0, -50]);

// Ref for confetti
const confettiRef = useRef(null);

// Gestion du scroll pour l'effet flou de la Navbar
useEffect(() => {
const handleScroll = () => setScrolled(window.scrollY > 50);
window.addEventListener('scroll', handleScroll);
return () => window.removeEventListener('scroll', handleScroll);
}, []);

// --- ACTIONS ---

const handleGenerateInvoice = async () => {
setLoading(true);
setError(null);
setPaymentProgress(0);

// Simulate progress
const progressInterval = setInterval(() => {
setPaymentProgress(prev => {
if (prev >= 90) {
clearInterval(progressInterval);
return 90;
}
return prev + 10;
});
}, 100);

try {
const response = await fetch(`${API_URL}/invoice`, {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({
sats: Number(amount),
description: `Don Fasochain: ${selectedCause.title}` 
})
});

const data = await response.json();
clearInterval(progressInterval);
setPaymentProgress(100);

if (data.request) {
setInvoice(data.request);
setTimeout(() => setStep(2), 500);
} else {
throw new Error("Impossible de générer la facture.");
}
} catch (err) {
clearInterval(progressInterval);
setError("Erreur de connexion au serveur LND. Vérifiez que le backend est actif.");
console.error(err);
setPaymentProgress(0);
} finally {
setLoading(false);
}
};

const copyToClipboard = async () => {
try {
await navigator.clipboard.writeText(invoice);
setCopied(true);
setShowSuccess(true);
setTimeout(() => {
setCopied(false);
setShowSuccess(false);
}, 2000);
} catch (err) {
console.error('Failed to copy:', err);
}
};

const handleFinalize = () => {
setStep(3);
setTotalDonations(prev => prev + amount);
setActiveDonors(prev => prev + 1);

// Enhanced confetti with multiple bursts
const duration = 3 * 1000;
const animationEnd = Date.now() + duration;
const defaults = { startVelocity: 30, spread: 360, ticks: 60, zIndex: 0 };

function randomInRange(min, max) {
return Math.random() * (max - min) + min;
}

const interval = setInterval(function() {
const timeLeft = animationEnd - Date.now();

if (timeLeft <= 0) {
return clearInterval(interval);
}

const particleCount = 50 * (timeLeft / duration);

// Confetti from left
confetti(Object.assign({}, defaults, {
particleCount,
origin: { x: randomInRange(0.1, 0.3), y: Math.random() - 0.2 },
colors: [COLORS.red, COLORS.green, COLORS.yellow]
}));

// Confetti from right
confetti(Object.assign({}, defaults, {
particleCount,
origin: { x: randomInRange(0.7, 0.9), y: Math.random() - 0.2 },
colors: [COLORS.red, COLORS.green, COLORS.yellow]
}));
}, 250);
};

 // --- DONATION FLOW COMPONENTS ---

const DonationFlow = () => {
